obs={ (1,1,0):40.4657,(2,0,0):58.6472,(2,1,1):73.6212,(2,2,0):87.7467,(3,1,0):101.4417,(3,2,1):132.625}
hkl=list(obs.keys()); tt=np.array([obs[k] for k in hkl])
