for a in [3.147,3.150,3.153,3.156,3.159,3.165]:
    zs=np.linspace(-0.3,0.3,601)
    ss=[np.sum((pred(a,z)-tt)**2) for z in zs]
    i=int(np.argmin(ss))
    print(a, round(zs[i],3), round(ss[i],4), np.round(pred(a,zs[i])-tt,3))

